  'Keep this computer awake while tasks run': '任务运行时保持此计算机处于唤醒状态',
  'macOS only. Prevents idle sleep while a task is working, so it keeps going while you follow it here.':
    '仅限 macOS。防止任务执行时空闲睡眠，因此当您在此处执行任务时，任务会继续进行。',
  'Model modes (experimental)': '模型模式（实验）',
  'Tune & Maestro modes (experimental)': 'Tune & Maestro 模式（实验性）',
